pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _am, uint256 _unlockTime, uint256 _deposit, address _sender) public {
        // Restrict inputs to avoid reverts from invalid conditions
        vm.assume(_deposit >= 1 ether); // Ensure MinSum is met
        vm.assume(_am <= _deposit);
        vm.assume(_am > 0);
        vm.assume(_unlockTime <= block.timestamp); // Ensure unlockTime is in the past
        vm.assume(_sender != address(0));

        // Fund the test contract to send ETH
        vm.deal(address(this), _deposit);

        // Set up: deposit as _sender
        vm.prank(_sender);
        c.Put{value: _deposit}(_unlockTime);

        // Now call Collect on behalf of _sender
        vm.prank(_sender);
        // Try to collect, wrapping in try/catch to handle potential revert
        bool collectReverted;
        try c.Collect(_am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // The general rule: Collect should NOT revert if conditions are met
        // (balance >= MinSum, balance >= _am, block.timestamp > unlockTime)
        // In the reference, it succeeds; in the mutant with fixed gas 100000, 
        // it may revert if the recipient's fallback needs more gas.
        // Since we control the recipient (address(this)), 
        // and our fallback does trivial work, both should succeed.
        // However, to capture the difference we assert that Collect did NOT revert.
        assertTrue(!collectReverted);
    }
}

