pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 withdrawAmount, uint256 unlockTimeOffset) public {
        // Bound inputs to avoid overflow and unrealistic values
        vm.assume(sender != address(0));
        initialBalance = bound(initialBalance, 1 ether, 100000 ether);
        withdrawAmount = bound(withdrawAmount, 1, initialBalance);
        unlockTimeOffset = bound(unlockTimeOffset, 0, 365 days);

        // Setup: fund the sender and set unlock time in the past so Collect can succeed
        vm.deal(address(c), initialBalance);
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put{value: initialBalance}(block.timestamp - 1);

        // Ensure MinSum condition is met (MinSum = 1 ether)
        vm.assume(initialBalance >= c.MinSum());

        // Record balance before Collect
        uint256 balanceBefore = c.Acc(sender).balance;

        // Call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        // Assertion: If Collect succeeded, balance decreased by exactly withdrawAmount
        if (success) {
            uint256 balanceAfter = c.Acc(sender).balance;
            assertTrue(balanceAfter + withdrawAmount == balanceBefore, "Balance reduction mismatch");
        }
    }
}

