pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        // Assume the user deposits some ether
        vm.deal(address(this), 2 ether);
        c.Put{value: 1 ether}(0);

        // Now try to collect an amount that is less than MinSum (1 ether)
        // and also less than the deposited balance
        vm.assume(am < 1 ether);
        vm.assume(am > 0);

        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));
        uint256 balanceAfter = address(c).balance;

        // In the reference, if balanceBefore >= MinSum, the withdraw would happen,
        // but we made sure am < MinSum, so the condition acc.balance >= MinSum in reference
        // prevents the withdrawal. In the mutant, since that condition is removed,
        // the withdrawal would succeed.
        // The rule: if the collected amount is less than MinSum, the contract's balance
        // should not decrease (i.e., no ether transferred out).
        bool balanceDecreased = (balanceAfter < balanceBefore);

        // The reference ensures balanceDecreased is false (withdrawal blocked)
        // The mutant allows it to be true (withdrawal succeeds)
        assertTrue(!balanceDecreased, "Balance should not decrease when am < MinSum");
    }
}

