pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, uint256 am, uint256 putValue) public {
        vm.assume(sender != address(0));

        // Give some initial balance to the sender
        vm.deal(sender, putValue + am);

        // Call Put to add balance
        vm.prank(sender);
        (bool putOk, ) = address(c).call{value: putValue}(abi.encodeWithSelector(c.Put.selector, 0));
        vm.assume(putOk); // Put should always succeed when well-funded

        // Now try Collect
        vm.prank(sender);
        (bool collected, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, am));

        // Read the sender's balance after the attempt
        uint256 balance = c.Acc(sender).balance;

        // General rule: If Collect succeeded, balance must be >= MinSum, and no underflow occurred.
        // Reference: Collect would have checked balance >= MinSum, so post-state balance >= MinSum or transaction reverts.
        // For buggy version: Collect could succeed even if balance < MinSum, leaving balance < MinSum.
        assertTrue(!collected || balance >= c.MinSum());
    }
}

