pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 seed) public {
        // Ensure am is within reasonable bounds (not zero for a successful collect, but bound for testing)
        am = bound(am, 1, 1 ether);
        // Fund the contract with 1 ether for potential sends
        vm.deal(address(c), 2 ether);
        // Use a test user
        address user = vm.addr(seed);
        vm.prank(user);
        // First, put some ETH (enough to cover the collect amount)
        // We need to call Put with a future unlock time (or at least a time > block.timestamp) to allow Collect later
        uint256 futureUnlock = block.timestamp + 1000;
        // Fund user with enough to put
        vm.deal(user, 1 ether);
        // Put call - transfer am + some buffer
        c.Put{value: 1 ether}(futureUnlock);
        // Simulate time passing
        vm.warp(block.timestamp + 1001);
        // Record the unlockTime before collect
        uint256 unlockBefore = c.Acc(user).unlockTime;
        // Attempt a Collect of 'am'
        // We need to ensure the balance is >= MinSum (1 ether) and >= am
        // From the put, balance is 1 ether, MinSum is 1 ether, so am must be <= 1 ether
        if (c.Acc(user).balance >= c.MinSum() && c.Acc(user).balance >= am && block.timestamp > c.Acc(user).unlockTime) {
            // This Collect should succeed (no reentrancy calls)
            // But to avoid reentrancy issues, we just call directly
            c.Collect(am);
            // After Collect, unlockTime should remain unchanged because Collect does not modify unlockTime
            uint256 unlockAfter = c.Acc(user).unlockTime;
            assertTrue(unlockBefore == unlockAfter);
        }
        // If condition not met, the collect would revert; we don't need to test that case.
    }
}

